import java.util.*;

class Solution {
    public void captureTrapped(char[][] board) {
        int r = board.length, c = board[0].length;
        for (int i = 0; i < r; i++) { mark(board, i, 0); mark(board, i, c - 1); }
        for (int j = 0; j < c; j++) { mark(board, 0, j); mark(board, r - 1, j); }
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                if (board[i][j] == 'O') board[i][j] = 'X'; // trapped
                else if (board[i][j] == 'S') board[i][j] = 'O'; // safe, restore
            }
    }

    // flood fill from (i, j), marking connected 'O' cells as safe 'S'
    private void mark(char[][] b, int i, int j) {
        if (b[i][j] != 'O') return;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        b[i][j] = 'S';
        stack.push(new int[]{i, j});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            for (int[] d : dirs) {
                int x = cur[0] + d[0], y = cur[1] + d[1];
                if (x >= 0 && y >= 0 && x < b.length && y < b[0].length && b[x][y] == 'O') {
                    b[x][y] = 'S';
                    stack.push(new int[]{x, y});
                }
            }
        }
    }
}

