class Solution:
    def captureTrapped(self, board: List[List[str]]) -> None:
        r, c = len(board), len(board[0])
        st = [(i, j) for i in range(r) for j in range(c) if (i in (0, r-1) or j in (0, c-1)) and board[i][j] == "O"]
        for i, j in st: board[i][j] = "S"
        while st:
            i, j = st.pop()
            for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                if 0 <= x < r and 0 <= y < c and board[x][y] == "O":
                    board[x][y] = "S"; st.append((x, y))
        for i in range(r):
            for j in range(c):
                board[i][j] = "O" if board[i][j] == "S" else "X"

