function captureTrapped(board) {
  const r = board.length, c = board[0].length, st = [];
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++)
    if ((i === 0 || i === r-1 || j === 0 || j === c-1) && board[i][j] === "O") { board[i][j] = "S"; st.push([i, j]); }
  while (st.length) {
    const [i, j] = st.pop();
    for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]])
      if (x >= 0 && x < r && y >= 0 && y < c && board[x][y] === "O") { board[x][y] = "S"; st.push([x, y]); }
  }
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) board[i][j] = board[i][j] === "S" ? "O" : "X";
}
